import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import '../theme/app_colors.dart';
import '../theme/app_text_styles.dart';

/// The CampusHub logo tile (generated by tool/generate_brand_assets.py),
/// optionally with the "CampusHub" wordmark and tagline underneath.
class AppLogo extends StatelessWidget {
  static const String assetPath = 'assets/branding/logo.png';

  final double size;
  final bool showWordmark;
  final bool showTagline;

  /// Use light text for the wordmark (for gradient / dark backgrounds).
  final bool onDark;

  /// Draws a white ring around the tile so it stands out on brand gradients.
  final bool outlined;

  const AppLogo({
    super.key,
    this.size = 88,
    this.showWordmark = true,
    this.showTagline = true,
    this.onDark = false,
    this.outlined = false,
  });

  @override
  Widget build(BuildContext context) {
    final radius = BorderRadius.circular(size * 0.225);
    final ring = outlined ? size * 0.05 : 0.0;

    final tile = Container(
      padding: EdgeInsets.all(ring),
      decoration: BoxDecoration(
        color: outlined ? Colors.white.withValues(alpha: 0.95) : null,
        borderRadius: BorderRadius.circular(size * 0.225 + ring),
        boxShadow: [
          BoxShadow(
            color: (onDark ? Colors.black : AppColors.primary).withValues(
              alpha: onDark ? 0.28 : 0.22,
            ),
            blurRadius: size * 0.3,
            offset: Offset(0, size * 0.1),
          ),
        ],
      ),
      child: ClipRRect(
        borderRadius: radius,
        child: Image.asset(
          assetPath,
          width: size,
          height: size,
          filterQuality: FilterQuality.medium,
          gaplessPlayback: true,
        ),
      ),
    );

    if (!showWordmark) return tile;

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        tile,
        SizedBox(height: size * 0.24),
        AppWordmark(onDark: onDark),
        if (showTagline) ...[
          const SizedBox(height: 4),
          Text(
            'Your campus, simplified.',
            style: AppTextStyles.bodySecondary.copyWith(
              color: onDark ? Colors.white.withValues(alpha: 0.7) : null,
            ),
          ),
        ],
      ],
    );
  }
}

/// "Campus" + accent-coloured "Hub".
class AppWordmark extends StatelessWidget {
  final bool onDark;
  final double fontSize;
  const AppWordmark({super.key, this.onDark = false, this.fontSize = 28});

  @override
  Widget build(BuildContext context) {
    final base = GoogleFonts.poppins(
      fontSize: fontSize,
      fontWeight: FontWeight.w700,
      letterSpacing: -0.5,
      color: onDark ? Colors.white : AppColors.textPrimary,
    );
    return Text.rich(
      TextSpan(
        children: [
          const TextSpan(text: 'Campus'),
          TextSpan(
            text: 'Hub',
            style: TextStyle(
              color: onDark ? const Color(0xFF5EEAD4) : AppColors.secondary,
            ),
          ),
        ],
      ),
      style: base,
    );
  }
}
